-- TPC-DS Test_Query Query 101
-- Based on: query13.tpl (medium)
-- Variation: 20

select avg(ss_quantity) ,avg(ss_ext_sales_price) ,avg(ss_ext_wholesale_cost) ,sum(ss_ext_wholesale_cost) from store_sales ,store ,customer_demographics ,household_demographics ,customer_address ,date_dim where s_store_sk = ss_store_sk and  ss_sold_date_sk = d_date_sk and d_year = 1989 and((ss_hdemo_sk=hd_demo_sk and cd_demo_sk = ss_cdemo_sk and cd_marital_status = 'MS.1' and cd_education_status = 'ES.2' and ss_sales_price between 100.1 and 150.1 and hd_dep_count = 2 )or (ss_hdemo_sk=hd_demo_sk and cd_demo_sk = ss_cdemo_sk and cd_marital_status = 'MS.1' and cd_education_status = 'ES.2' and ss_sales_price between 50.1 and 100.1 and hd_dep_count = 1 ) or (ss_hdemo_sk=hd_demo_sk and cd_demo_sk = ss_cdemo_sk and cd_marital_status = 'MS.2' and cd_education_status = 'ES.4' and ss_sales_price between 150.2 and 200.1 and hd_dep_count = 2 )) and((ss_addr_sk = ca_address_sk and ca_country = 'United States' and ca_state in ('STATE.2', 'STATE.1', 'STATE.4') and ss_net_profit between 100 and 204 ) or (ss_addr_sk = ca_address_sk and ca_country = 'United States' and ca_state in ('STATE.3', 'STATE.7', 'STATE.5') and ss_net_profit between 150 and 310 ) or (ss_addr_sk = ca_address_sk and ca_country = 'United States' and ca_state in ('STATE.7', 'STATE.8', 'STATE.11') and ss_net_profit between 47 and 244 ));
